const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location and time
  const nyamulagira = ee.Geometry.Point([29.20, -1.41]);
  const roi = nyamulagira.buffer(50000); // 50km radius to capture plume drift

  const startDate = '2025-02-20';
  const endDate = '2025-02-21';

  console.log("Searching for Landsat 8 images at Nyamulagira on Feb 20, 2025...");

  // 2. Get Landsat 8 Collection
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(nyamulagira)
    .filterDate(startDate, endDate);

  const count = await collection.size().getInfo();
  console.log(`Landsat 8 images found: ${count}`);

  if (count === 0) {
    console.log("No Landsat 8 imagery available for this date/location.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Get the image and check aerosol band (SR_QA_AEROSOL) and visual bands
  const image = collection.first();

  // Scale factors for Landsat 8 Collection 2
  const opticalBands = image.select(['SR_B.*']).multiply(0.0000275).add(-0.2);

  // Check valid pixel count in the region
  const validPixels = await opticalBands.select('SR_B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B4').getInfo();

  console.log(`Valid pixels in ROI: ${validPixels}`);

  if (validPixels === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Analyze plume direction using aerosol optical depth indicators
  // Create east and west regions from volcano center
  const westRegion = ee.Geometry.Rectangle([29.10, -1.51, 29.20, -1.31]);
  const eastRegion = ee.Geometry.Rectangle([29.20, -1.51, 29.40, -1.31]);

  // Use blue band (often elevated in volcanic plumes) and aerosol indicators
  const blueBand = opticalBands.select('SR_B2');

  const westMean = await blueBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B2').getInfo();

  const eastMean = await blueBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: eastRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B2').getInfo();

  console.log(`Blue band mean - West: ${westMean ? westMean.toFixed(4) : 'null'}`);
  console.log(`Blue band mean - East: ${eastMean ? eastMean.toFixed(4) : 'null'}`);

  if (westMean === null || eastMean === null) {
    console.log("Failed to calculate plume indicators.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Determine if plume drifted eastward
  // Eastward drift indicated by higher reflectance/aerosol in east vs west
  const driftRatio = eastMean / westMean;
  console.log(`East/West ratio: ${driftRatio.toFixed(3)}`);

  // If eastern region shows significantly higher signal (>1.2x), plume drifted east
  if (driftRatio > 1.2) {
    console.log("Evidence of eastward plume drift detected.");
    console.log("<answer>A</answer>");
  } else {
    console.log("No clear eastward plume drift detected.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
